{
  "findings": [
    {
      "check_id": "CKV_GCP_106",
      "title": "Unrestricted HTTP access on port 80",
      "resource": "google_compute_firewall.allow_http_https",
      "severity": "MEDIUM",
      "explanation": "The ingress rule exposes unencrypted HTTP port 80 to every IPv4 address. Traffic may be intercepted or modified, and the file does not establish that this port only performs a secure redirect."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Unrestricted access on TCP port 8080",
      "resource": "google_compute_firewall.allow_http_https",
      "severity": "MEDIUM",
      "explanation": "TCP port 8080 is exposed to the entire internet and is commonly used for alternate HTTP services, proxies, and administrative interfaces. No source restriction or other justification for this exposure is present in the file."
    }
  ],
  "patched_code": "resource \"google_compute_firewall\" \"allow_http_https\" {\n  name    = \"digital-asset-trading-platform-firewall-web\"\n  network = google_compute_network.digital_asset_trading_vpc.name\n  allow {\n    protocol = \"tcp\"\n    ports    = [\"443\"]\n  }\n  source_ranges = [\"0.0.0.0/0\"]\n  target_tags   = [\"web-server\"]\n}\n",
  "fix_summary": "Removed publicly exposed plaintext ports 80 and 8080 from the firewall rule. Public ingress is now limited to HTTPS on TCP port 443."
}
